-- Performance history import: Franchisee_Stats_Latest.xlsx, sheet "Data 1" (as at 24 Nov 2026).
-- 3518 months with figures (months where turnover and jobs were both zero are left out).
-- Run AFTER franchisee_portal.sql. Safe to re-run: existing months are updated, links to franchisees are kept.
-- Then link each territory to its current franchisee in the portal: Performance > Link imported history.
begin;
on conflict (territory_label, period) do update
  set turnover_incl = excluded.turnover_incl, turnover_excl = excluded.turnover_excl, jobs = excluded.jobs;
commit;
select count(*) as months_loaded, count(distinct territory_label) as territories from public.performance_history;
